@model MyFirstApp.Models.Product

<!-- Razor switches to HTML mode between tags -->
<div class="product-details">
    <h1>@Model.Name</h1>
    <p class="price">@Model.Price.ToString("C")</p>
    <p class="category">Category: @Model.Category</p>

    @if (Model.Price > 100)
    {
        <span class="badge">Premium</span>
    }
    else
    {
        <span class="badge">Budget</span>
    }

    <a asp-action="Index" asp-controller="Products">
        Back to Products
    </a>
</div>

@model IEnumerable<MyFirstApp.Models.Product>

<h1>Our Products</h1>

@if (!Model.Any())
{
    <p>No products available yet.</p>
}
else
{
    <ul class="product-list">
        @foreach (var product in Model)
        {
            <li>
                <a asp-action="Details" asp-route-id="@product.Id">
                    @product.Name — @product.Price.ToString("C")
                </a>
            </li>
        }
    </ul>
}
